    char *path = identify_http_method(request, buffer);
    if (UNLIKELY(!path))
        return HTTP_NOT_ALLOWED;

    buffer = identify_http_path(request, path);
    if (UNLIKELY(!buffer))
        return HTTP_BAD_REQUEST;

    char *end = helper->crlfcrlf ? helper->crlfcrlf + sizeof("\r\n\r\n") - 1
